import * as T from '/src/vendor/three/three.module.js';
const wait=ms=>new Promise(r=>setTimeout(r,ms));
/** Mede pixels afetados na projeção da personagem e na cena inteira. */
function differences(on,off,box,width,height){let actor=0,scene=0;for(let y=0;y<height;y+=2)for(let x=0;x<width;x+=2){const i=(y*width+x)*4,d=(off[i]+off[i+1]+off[i+2])-(on[i]+on[i+1]+on[i+2]);if(d>5){scene++;if(x>=box.left&&x<=box.right&&y>=box.top&&y<=box.bottom)actor++;}}return {actor,scene};}
/** Executa enquadramentos controlados no renderer real, sem passos artificiais da simulação. */
export async function run(){
 const g=window.game;await g.assetsReady;g.startDebugPhase('bear-chase','NORMAL');
 let c;for(let i=0;i<300;i++){c=g.state.toyRoomInstance.instance.chase;if(c.error)throw Error(c.error);if(c.ready)break;await wait(100);}if(!c.ready)throw Error('Perseguição não ficou pronta');g.setPaused(true);
 const r=c.renderer,l=r.lighting,canvas=c.canvas,ctx=c.ctx,resultados=[],capturas=[];
 const shot=nome=>capturas.push({nome,data:canvas.toDataURL('image/png')});
 for(const [width,height]of [[1280,800],[390,844],[844,390]]){
  canvas.width=width;canvas.height=height;
  for(const [distance,x]of [[14,0],[82,-3],[338,3],[700,0]]){
   Object.assign(c.state,{stage:'RUNNING',distance,x,bearX:0,gap:18,time:10+distance/10,age:20,stumble:0,immunity:0});const saved=JSON.stringify(c.state);c.render();
   const on=ctx.getImageData(0,0,width,height).data.slice(),calls=r.renderer.info.render.calls,triangles=r.renderer.info.render.triangles,update=l.update;
   const bb=new T.Box3().setFromObject(r.girl),points=[];for(const x of [bb.min.x,bb.max.x])for(const y of [bb.min.y,bb.max.y])for(const z of [bb.min.z,bb.max.z])points.push(new T.Vector3(x,y,z).project(r.camera));
   const box={left:(Math.min(...points.map(p=>p.x))+1)*width/2,right:(Math.max(...points.map(p=>p.x))+1)*width/2,top:(1-Math.max(...points.map(p=>p.y)))*height/2,bottom:(1-Math.min(...points.map(p=>p.y)))*height/2};
   l.update=()=>{};const intensity=l.fairy.intensity;l.fairy.intensity=0;c.render();const unlit=ctx.getImageData(0,0,width,height).data.slice();l.fairy.intensity=intensity;l.fairy.castShadow=false;c.render();const noShadow=ctx.getImageData(0,0,width,height).data.slice();l.fairy.castShadow=true;l.update=update;c.render();
   const illumination=differences(unlit,on,box,width,height),shadow=differences(on,noShadow,box,width,height);
   const pos=r.fairy.position.clone().project(r.camera),head=new T.Vector3(0,.42,0).applyMatrix4(r.girlModel.head.matrixWorld);
   resultados.push({width,height,distance,x,calls,triangles,iluminadosMenina:illumination.actor,sombraMenina:shadow.actor,sombraCena:shadow.scene,sombrasAtivas:l.lights.filter(o=>o.castShadow&&o.visible).length,mapas:l.lights.filter(o=>o.shadow.map).length,resolucaoFada:l.fairy.shadow.mapSize.x,estadoPreservado:saved===JSON.stringify(c.state),sobreCabeca:r.fairy.position.y>head.y+.2&&Math.hypot(r.fairy.position.x-head.x,r.fairy.position.z-head.z)<.5,projecaoVisivel:Math.abs(pos.x)<1&&Math.abs(pos.y)<1,resources:r.resources.size});
   if(distance===14||distance===338){shot('jogo-'+width+'-'+distance);l.update=()=>{};l.fairy.intensity=0;c.render();shot('sem-luz-'+width+'-'+distance);l.fairy.intensity=intensity;l.update=update;c.render();}
  }
 }
 const f=r.fairyModel;let triangles=0,meshes=0;f.root.traverse(o=>{if(o.isMesh){meshes++;triangles+=(o.geometry.index?.count??o.geometry.attributes.position.count)/3;}});
 const box=new T.Box3().setFromObject(f.root),modelo={malhas:meshes,triangulos:triangles,profundidade:box.max.z-box.min.z};
 const pose=()=>JSON.stringify({p:f.root.position.toArray(),q:f.root.quaternion.toArray(),asas:f.wings.map(w=>w.rotation.toArray())});const before=pose();f.apply(c.state,r.girlModel);const pausa=before===pose();
 const viewer=new T.Scene();viewer.background=new T.Color('#4d4245');viewer.add(new T.HemisphereLight('#fff4dc','#817380',2));const key=new T.DirectionalLight('#ffffff',2.5);key.position.set(-2,3,-3);viewer.add(key);
 const model=f.root.clone(true);model.position.set(0,0,0);model.rotation.set(0,0,0);viewer.add(model);const camera=new T.PerspectiveCamera(35,1,.01,10);r.renderer.setSize(640,640,false);canvas.width=canvas.height=640;
 for(const [name,z]of [['frente',-1.8],['costas',1.8]]){camera.position.set(.8,.72,z);camera.lookAt(0,.36,0);r.renderer.render(viewer,camera);ctx.drawImage(r.renderer.domElement,0,0,640,640);shot('modelo-'+name);}
 const resources=[...r.resources],disposed=new Set();for(const resource of resources)resource.addEventListener('dispose',()=>disposed.add(resource));r.destroy();r.destroy();const descarte=r.resources.size===0&&resources.every(o=>disposed.has(o));
 return {resultados,modelo,pausa,descarte,capturas};
}
